package eventbus

import "fmt"

func (b *Bus) dispatch(e any) error {
	switch msg := e.(type) {
	case *OrderPlaced:
		b.orders <- msg
	case Metadata:
		b.audit(msg.TraceID)
	default:
		return fmt.Errorf("unhandled event %T", e)
	}

	meta, ok := e.(Metadata)
	if !ok {
		return nil
	}
	b.audit(meta.TraceID)
	return nil
}

