package ingest

// Map applies fn to every element, preserving order.
func Map[T any, U any](in []T, fn func(T) U) []U {
	out := make([]U, 0, len(in))
	for _, v := range in {
		out = append(out, fn(v))
	}
	return out
}

func Transform(rec map[string]string, opts Options) (map[string]string, error) {
	out := make(map[string]string, len(rec))
	for k, v := range rec {
		out[k] = opts.Rename(k) + v
	}
	return out, nil
}

